script:
(function () {
  'use strict';
  // Debt snowball. The monthly budget is fixed at (sum of all minimum payments + extra payment).
  // Each month every open debt is charged interest = balance x APR / 12 (rounded to the cent),
  // then gets its own minimum (capped at what it owes); everything left over - the extra plus
  // the minimums of debts already cleared - goes to the focus debt, the first open debt in the
  // payoff order (spilling to the next one if the focus is cleared mid-month). Orders: smallest
  // starting balance first (ties -> higher APR), highest APR first (ties -> smaller balance), or
  // the user's own order as listed. "Snowball payment" = budget minus the minimums of the other
  // debts still open in the month a debt becomes the focus. "Minimums only" pays each debt its
  // own minimum with no extra and no rollover.
  // Verified (scratchpad tests/b3debt/sb.test.js):
  //   one debt of $10,000 at 12% with a $222.45 minimum (closed-form level payment $222.44,
  //   rounded up) and $0 extra -> 60 months, interest within $0.10 of the closed form;
  //   two debts ($500 at 0% min $50 and $1,000 at 0% min $50, $100 extra) -> the $500 debt
  //   gets $150, $150, $150, $50 and is cleared in month 4 (the unused $100 spills to the next
  //   debt), its $50 minimum rolls over to give the $1,000 debt a $200 snowball, and the plan
  //   ends in month 8 = ceil(1,500 / 200);
  //   with zero interest the payoff month equals total debt / budget rounded up, for any order;
  //   total paid = starting balances + interest; the default four debts give the same snowball
  //   results as an independent month-by-month re-implementation in the test;
  //   custom order follows the listed order and avalanche never costs more interest than the
  //   snowball across 1,000 random debt sets.
  var MAX_MONTHS = 1200;
  var MAX_DEBTS = 10;
  var DEFAULTS = [
    { name: 'Credit card', balance: 5800, apr: 22.99, min: 170 },
    { name: 'Store card', balance: 900, apr: 26.99, min: 35 },
    { name: 'Car loan', balance: 11500, apr: 6.9, min: 340 },
    { name: 'Medical bill', balance: 2400, apr: 0, min: 100 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var rowCounter = 0;

  function cents(x) { return Math.round(x * 100) / 100; }

  function payoffOrder(debts, strategy) {
    var idx = debts.map(function (d, i) { return i; });
    if (strategy === 'custom') return idx;
    idx.sort(function (a, b) {
      var da = debts[a], db = debts[b];
      if (strategy === 'avalanche') return (db.apr - da.apr) || (da.balance - db.balance) || (a - b);
      return (da.balance - db.balance) || (db.apr - da.apr) || (a - b);
    });
    return idx;
  }

  // debts: [{ balance, apr (decimal), min }]; strategy: 'minimum' | 'snowball' | 'avalanche' | 'custom'.
  function simulate(debts, extra, strategy, keepMonths) {
    var n = debts.length, bal = debts.map(function (d) { return d.balance; });
    var paidOffMonth = debts.map(function () { return 0; });
    var snowPay = debts.map(function () { return 0; });
    var order = payoffOrder(debts, strategy);
    var budget = debts.reduce(function (s, d) { return s + d.min; }, 0) + extra;
    var totalInterest = 0, totalPaid = 0, months = [];
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var i, k, focus = -1, open = 0;
      if (strategy !== 'minimum') {
        for (k = 0; k < n; k++) if (bal[order[k]] > 0.005) { focus = order[k]; break; }
        if (focus >= 0 && !snowPay[focus]) {
          var others = 0;
          for (i = 0; i < n; i++) if (i !== focus && bal[i] > 0.005) others += debts[i].min;
          snowPay[focus] = budget - others;
        }
      }
      var pays = debts.map(function () { return 0; }), monthInterest = 0;
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var interest = cents(bal[i] * debts[i].apr / 12);
        bal[i] += interest; monthInterest += interest;
      }
      totalInterest += monthInterest;
      var avail = budget;
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var pay = Math.min(debts[i].min, bal[i]);
        bal[i] = cents(bal[i] - pay); pays[i] += pay; avail -= pay;
      }
      if (strategy !== 'minimum') {
        for (k = 0; k < n && avail > 0.005; k++) {
          var j = order[k];
          if (bal[j] <= 0.005) continue;
          var more = Math.min(avail, bal[j]);
          bal[j] = cents(bal[j] - more); pays[j] += more; avail -= more;
        }
      }
      var cleared = [];
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) { bal[i] = 0; if (!paidOffMonth[i] && pays[i] > 0) { paidOffMonth[i] = m; cleared.push(i); } } else open++;
      }
      var monthPaid = pays.reduce(function (s, p) { return s + p; }, 0);
      totalPaid += monthPaid;
      if (keepMonths) months.push({ focus: focus, pays: pays, cleared: cleared, paid: monthPaid, remaining: bal.reduce(function (s, b) { return s + b; }, 0) });
      if (open === 0) return { paidOff: true, months: m, interest: totalInterest, paid: totalPaid, payoffMonth: paidOffMonth, snowPay: snowPay, order: order, budget: budget, rows: months };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: totalInterest, paid: totalPaid, payoffMonth: paidOffMonth, snowPay: snowPay, order: order, budget: budget, rows: months };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells, header) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var c = document.createElement(header ? 'th' : 'td');
      if (header) c.setAttribute('scope', 'col');
      c.textContent = text;
      tr.appendChild(c);
    });
    body.appendChild(tr);
  }

  // ---- Debt rows (built with DOM methods; user text is only ever set as values/textContent) ----
  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function smallButton(text, attr) {
    var b = el('button', 'button-secondary h-9 px-3 text-sm', text);
    b.type = 'button';
    b.setAttribute(attr, '');
    return b;
  }

  function useCustomOrder() {
    var select = document.getElementById('sbOrder');
    if (select.value !== 'custom') select.value = 'custom';
  }

  function addDebtRow(d) {
    var list = document.getElementById('sbDebts');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-debt-row', String(n));
    var head = el('div', 'flex flex-wrap items-center justify-between gap-2');
    var title = el('p', 'text-sm font-semibold text-ink', 'Debt');
    title.setAttribute('data-debt-title', '');
    var buttons = el('div', 'flex flex-wrap gap-2');
    var up = smallButton('Move up', 'data-up'), down = smallButton('Move down', 'data-down'), remove = smallButton('Remove', 'data-remove');
    up.addEventListener('click', function () {
      var prev = row.previousElementSibling;
      if (!prev) return;
      list.insertBefore(row, prev);
      useCustomOrder(); refreshRows(); update();
    });
    down.addEventListener('click', function () {
      var next = row.nextElementSibling;
      if (!next) return;
      list.insertBefore(next, row);
      useCustomOrder(); refreshRows(); update();
    });
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-debt-row]').length <= 1) return;
      row.remove();
      refreshRows(); update();
    });
    buttons.appendChild(up); buttons.appendChild(down); buttons.appendChild(remove);
    head.appendChild(title); head.appendChild(buttons);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'sbName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'sbName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = d.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('sbBal' + n, 'Balance', d.balance, '$', true, '100'));
    pair.appendChild(numberField('sbApr' + n, 'APR', d.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('sbMin' + n, 'Minimum monthly payment', d.min, '$', true, '5'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('sbDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var label = 'debt ' + (i + 1);
      row.querySelector('[data-debt-title]').textContent = 'Debt ' + (i + 1);
      var up = row.querySelector('[data-up]'), down = row.querySelector('[data-down]'), rm = row.querySelector('[data-remove]');
      up.disabled = i === 0; down.disabled = i === rows.length - 1; rm.disabled = rows.length <= 1;
      up.setAttribute('aria-label', 'Move ' + label + ' up');
      down.setAttribute('aria-label', 'Move ' + label + ' down');
      rm.setAttribute('aria-label', 'Remove ' + label);
    });
    document.getElementById('sbAdd').disabled = rows.length >= MAX_DEBTS;
  }

  function readDebts() {
    var out = [], ok = true;
    var rows = document.getElementById('sbDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-debt-row');
      var name = document.getElementById('sbName' + n).value.trim() || ('Debt ' + (i + 1));
      var balEl = document.getElementById('sbBal' + n), aprEl = document.getElementById('sbApr' + n), minEl = document.getElementById('sbMin' + n);
      var bal = parseFloat(balEl.value), apr = aprEl.value.trim() === '' ? 0 : parseFloat(aprEl.value), min = parseFloat(minEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, minEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e8, badApr = isNaN(apr) || apr < 0 || apr > 100, badMin = isNaN(min) || min <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      minEl.setAttribute('aria-invalid', String(badMin));
      if (badBal || badApr || badMin) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100, min: min });
    });
    return { ok: ok, debts: out };
  }

  function clearResults() {
    ['sbDate', 'sbBudget', 'sbInterest', 'sbSaved'].forEach(function (id) { set(id, '–'); });
    set('sbDateNote', ''); set('sbSavedNote', '');
    document.getElementById('sbMinNote').hidden = true;
    clearBody('sbOrderBody'); clearBody('sbMonthsHead'); clearBody('sbMonths');
  }

  function aprText(apr) { return (apr * 100).toFixed(2).replace(/\.?0+$/, '') + '%'; }

  function update() {
    var error = document.getElementById('sbError');
    var extraEl = document.getElementById('sbExtra');
    var extra = extraEl.value.trim() === '' ? 0 : parseFloat(extraEl.value);
    var strategy = document.getElementById('sbOrder').value;
    var input = readDebts();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and minimum payments above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(extra) || extra < 0) problem = 'Enter an extra monthly payment of $0 or more.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }

    var debts = input.debts;
    var plan = simulate(debts, extra, strategy, true), mins = simulate(debts, 0, 'minimum', false);
    if (!plan.paidOff) {
      error.hidden = false;
      error.textContent = 'Your monthly budget does not keep up with the interest, so these debts are not paid off within 100 years. Raise the extra payment or the minimums.';
      clearResults();
      return;
    }
    error.hidden = true; error.textContent = '';

    set('sbDate', dateAfter(plan.months));
    set('sbDateNote', 'Debt-free in ' + duration(plan.months) + '.');
    set('sbBudget', money.format(plan.budget));
    set('sbInterest', money.format(plan.interest));
    if (mins.paidOff) {
      set('sbSaved', money.format(Math.max(mins.interest - plan.interest, 0)));
      set('sbSavedNote', mins.months > plan.months ? 'And debt-free ' + duration(mins.months - plan.months) + ' sooner.' : 'Same finish date as minimums only.');
    } else {
      set('sbSaved', 'Not comparable');
      set('sbSavedNote', 'Minimum payments alone never clear these debts.');
    }
    var minNote = document.getElementById('sbMinNote');
    minNote.hidden = mins.paidOff;
    if (!mins.paidOff) minNote.textContent = 'At least one minimum payment does not cover that debt’s monthly interest. The snowball still clears it once the rolled-over payments reach it.';

    var orderBody = clearBody('sbOrderBody');
    plan.order.forEach(function (i, step) {
      var d = debts[i];
      addRow(orderBody, [String(step + 1), d.name, money.format(d.balance), aprText(d.apr), money.format(d.min),
        plan.snowPay[i] ? money.format(plan.snowPay[i]) + '/mo' : 'Cleared by its minimum',
        dateAfter(plan.payoffMonth[i]) + ' (month ' + plan.payoffMonth[i] + ')']);
    });

    var head = clearBody('sbMonthsHead');
    var cols = ['Month', 'Date', 'Focus debt'];
    plan.order.forEach(function (i) { cols.push(debts[i].name); });
    cols.push('Total paid', 'Still owed');
    addRow(head, cols, true);
    var body = clearBody('sbMonths');
    plan.rows.forEach(function (r, k) {
      var cells = [String(k + 1), dateAfter(k + 1), r.focus >= 0 ? debts[r.focus].name : '–'];
      plan.order.forEach(function (i) {
        var p = r.pays[i];
        cells.push(p > 0 ? money.format(p) + (r.cleared.indexOf(i) >= 0 ? ' (paid off)' : '') : '–');
      });
      cells.push(money.format(r.paid), money.format(r.remaining));
      addRow(body, cells);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addDebtRow);
    var form = document.getElementById('sbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('sbAdd').addEventListener('click', function () {
      if (document.getElementById('sbDebts').querySelectorAll('[data-debt-row]').length >= MAX_DEBTS) return;
      addDebtRow({ name: '', balance: '', apr: '', min: '' });
      update();
    });
    update();
  });
})();
